package com.factory.copilot.service; import com.factory.copilot.entity.Machine; import com.factory.copilot.repository.MachineRepository; import org.springframework.stereotype.Service; import java.util.List; @Service public class MachineService { private final MachineRepository machineRepository; public MachineService(MachineRepository machineRepository) { this.machineRepository = machineRepository; } public List<Machine> getAllMachines() { return machineRepository.findAll(); } public Machine getMachineById(Long id) { return machineRepository.findById(id).orElse(null); } public Machine getMachineByCode(String machineCode) { return machineRepository.findByMachineCode(machineCode).orElse(null); } }
